<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class LkdYoungRepresentative extends Model {protected $fillable=['university_id','user_id','status','can_send_announcements','mailing_list_address','approved_at','approved_by']; protected $casts=['can_send_announcements'=>'boolean','approved_at'=>'datetime']; public function user(){return $this->belongsTo(User::class);} public function university(){return $this->belongsTo(Universities::class);}}
